 1→import { requireUser } from "@/lib/auth";
 2→import { checkPermission } from "@/lib/permissions";
 3→import { redirect } from "next/navigation";
 4→import { getDashboardRows } from "@/lib/queries";
 5→import SummaryPage from "@/components/summary-page";
 6→
 7→export default async function Summary() {
 8→  const user = await requireUser();
 9→  if (!checkPermission(user.role, "dashboard.summary", "view")) {
10→    redirect("/summary");
11→  }
12→
13→  const rows = getDashboardRows(user);
14→
15→  // Only count rows that represent actual recruitment requests
16→  const requestRows = rows.filter((r) => r.requestId !== null);
17→  const total = requestRows.length;
18→
19→  const completed = requestRows.filter((r) => {
20→    const step = r.values["현재단계"];
21→    return typeof step === "string" && (step.includes("완료") || step.includes("임용"));
22→  }).length;
23→
24→  const waiting = requestRows.filter((r) => {
25→    const step = r.values["현재단계"];
26→    return !step || step === "" || step === "대기";
27→  }).length;
28→
29→  const inProgress = total - completed - waiting;
30→
31→  const kpi = { total, inProgress, completed, waiting };
32→
33→  // Recent activity: based on most recent rows with requests
34→  const recentActivity = requestRows.slice(0, 5).map((r, i) => {
35→    const fieldName = (r.values["(최종) 초빙분야"] as string) || "채용";
36→    const currentStep = (r.values["현재단계"] as string) || "";
37→    const statusLabel = currentStep || "진행중";
38→
39→    let status: "complete" | "progress" | "waiting" = "progress";
40→    if (currentStep.includes("완료") || currentStep.includes("임용")) {
41→      status = "complete";
42→    } else if (!currentStep || currentStep === "대기") {
43→      status = "waiting";
44→    }
45→
46→    return {
47→      id: r.id,
48→      deptName: r.deptName || "",
49→      description: `${fieldName} ${statusLabel}`,
50→      status,
51→      timeAgo: `${i + 1}일 전`,
52→    };
53→  });
54→
55→  return <SummaryPage kpi={kpi} recentActivity={recentActivity} />;
56→}
