 48→export function updatePermissions(
 49→  role: string,
 50→  changes: { resource: string; action: string; allowed: boolean }[]
 51→): void {
 52→  const db = getDb();
 53→  const upsert = db.prepare(`
 54→    INSERT INTO permissions (role, resource, action, allowed)
 55→    VALUES (?, ?, ?, ?)
 56→    ON CONFLICT(role, resource, action)
 57→    DO UPDATE SET allowed = excluded.allowed, updated_at = CURRENT_TIMESTAMP
 58→  `);
 59→  const tx = db.transaction(() => {
 60→    for (const c of changes) {
 61→      upsert.run(role, c.resource, c.action, c.allowed ? 1 : 0);
 62→    }
 63→  });
 64→  tx();
 65→}
