"use client";

import { useState } from "react";
import SummaryPage from "@/components/summary-page";
import AllocationTable from "@/components/allocation-table";
import ProgressBoard from "@/components/progress-board";
import type {
  AuthUser,
  DashboardColumn,
  DashboardDetail,
  DashboardRow,
  UserRecord,
} from "@/lib/types";

type KpiData = {
  total: number;
  inProgress: number;
  completed: number;
  waiting: number;
};

type ActivityItem = {
  id: number;
  deptName: string;
  description: string;
  status: "complete" | "progress" | "waiting";
  timeAgo: string;
};

type Props = {
  kpi: KpiData;
  recentActivity: ActivityItem[];
  columns: DashboardColumn[];
  rows: DashboardRow[];
  initialDetail: DashboardDetail | null;
  currentUser: AuthUser;
  users: UserRecord[];
  departments: Array<{ deptCode: string; deptName: string }>;
};

const tabs = ["요약", "TO 배분표", "진행현황"] as const;

export default function DashboardTabs({
  kpi,
  recentActivity,
  columns,
  rows,
  initialDetail,
  currentUser,
  users,
  departments,
}: Props) {
  const [active, setActive] = useState<(typeof tabs)[number]>("요약");

  return (
    <div>
      <div style={{ marginBottom: 20 }}>
        <h2 style={{ fontSize: 18, fontWeight: 600, color: "#111", margin: 0 }}>대시보드</h2>
        <p style={{ fontSize: 12, color: "#888", margin: "2px 0 0" }}>채용 현황을 한눈에 확인합니다</p>
      </div>

      <div style={{ display: "flex", gap: 6, marginBottom: 20 }}>
        {tabs.map((tab) => (
          <button
            key={tab}
            onClick={() => setActive(tab)}
            style={{
              padding: "6px 16px",
              fontSize: 13,
              fontWeight: 500,
              cursor: "pointer",
              background: active === tab ? "#0a1f14" : "#fff",
              color: active === tab ? "#fff" : "#333",
              border: active === tab ? "none" : "1px solid #e5e7eb",
              borderRadius: 6,
            }}
          >
            {tab}
          </button>
        ))}
      </div>

      {active === "요약" && <SummaryPage kpi={kpi} recentActivity={recentActivity} />}
      {active === "TO 배분표" && (
        <AllocationTable
          columns={columns}
          rows={rows}
          initialDetail={initialDetail}
          currentUser={currentUser}
          users={users}
          departments={departments}
        />
      )}
      {active === "진행현황" && <ProgressBoard rows={rows} currentUser={currentUser} />}
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { Download } from "lucide-react";
import { AdminRequestSheet } from "@/components/admin-request-sheet";
import { AdminWorkflowTable } from "@/components/admin-workflow-table";
import type {
  AdminRequestSheetRow,
  AdminWorkflowColumn,
  AdminWorkflowMatrixRow,
} from "@/lib/types";

type Props = {
  requestRows: AdminRequestSheetRow[];
  workflowColumns: AdminWorkflowColumn[];
  workflowRows: AdminWorkflowMatrixRow[];
};

const tabs = ["채용요청", "워크플로우"] as const;

export default function DataTabs({ requestRows, workflowColumns, workflowRows }: Props) {
  const [active, setActive] = useState<(typeof tabs)[number]>("채용요청");

  return (
    <div>
      <div style={{ marginBottom: 20 }}>
        <h2 style={{ fontSize: 18, fontWeight: 600, color: "#111", margin: 0 }}>데이터 관리</h2>
        <p style={{ fontSize: 12, color: "#888", margin: "2px 0 0" }}>채용요청 및 워크플로우 데이터를 관리합니다</p>
      </div>

      <div style={{ display: "flex", gap: 6, marginBottom: 20, alignItems: "center" }}>
        {tabs.map((tab) => (
          <button
            key={tab}
            onClick={() => setActive(tab)}
            style={{
              padding: "6px 16px",
              fontSize: 13,
              fontWeight: 500,
              cursor: "pointer",
              background: active === tab ? "#0a1f14" : "#fff",
