            }}
          >
            {tab}
          </button>
        ))}
        {active === "워크플로우" && (
          <Link
            href="/api/admin/workflow/export"
            className="btn-secondary"
            style={{
              textDecoration: "none",
              display: "inline-flex",
              alignItems: "center",
              gap: 6,
              marginLeft: "auto",
            }}
          >
            <Download className="h-4 w-4" />
            엑셀 다운로드
          </Link>
        )}
      </div>

      {active === "채용요청" && (
        <div className="card" style={{ overflow: "visible" }}>
          <AdminRequestSheet initialRows={requestRows} />
        </div>
      )}
      {active === "워크플로우" && (
        <div className="card" style={{ overflow: "visible" }}>
          <AdminWorkflowTable columns={workflowColumns} initialRows={workflowRows} />
        </div>
      )}
    </div>
  );
}

import { requireUser, listUsers } from "@/lib/auth";
import { checkPermission } from "@/lib/permissions";
import { redirect } from "next/navigation";
import {
  getDashboardColumns,
  getDashboardRows,
  getDashboardDetail,
  getDepartmentOptions,
} from "@/lib/queries";
import DashboardTabs from "@/components/dashboard-tabs";

export default async function DashboardPage() {
  const user = await requireUser();
  if (!checkPermission(user.role, "dashboard", "view")) {
    redirect("/login");
  }

  const columns = getDashboardColumns();
  const rows = getDashboardRows(user);
  const initialDetail = rows[0] ? getDashboardDetail(rows[0].id, user) : null;
  const users = user.role === "VIP" ? listUsers() : [];
  const departments = user.role === "VIP" ? getDepartmentOptions() : [];

  // KPI computation (from summary page)
  const requestRows = rows.filter((r) => r.requestId !== null);
  const total = requestRows.length;

  const completed = requestRows.filter((r) => {
    const step = r.values["현재단계"];
    return typeof step === "string" && (step.includes("완료") || step.includes("임용"));
  }).length;

  const waiting = requestRows.filter((r) => {
    const step = r.values["현재단계"];
    return !step || step === "" || step === "대기";
  }).length;

  const inProgress = total - completed - waiting;

  const kpi = { total, inProgress, completed, waiting };

  // Recent activity
  const recentActivity = requestRows.slice(0, 5).map((r, i) => {
    const fieldName = (r.values["(최종) 초빙분야"] as string) || "채용";
    const currentStep = (r.values["현재단계"] as string) || "";
    const statusLabel = currentStep || "진행중";

    let status: "complete" | "progress" | "waiting" = "progress";
    if (currentStep.includes("완료") || currentStep.includes("임용")) {
      status = "complete";
    } else if (!currentStep || currentStep === "대기") {
      status = "waiting";
    }

    return {
      id: r.id,
      deptName: r.deptName || "",
      description: `${fieldName} ${statusLabel}`,
      status,
      timeAgo: `${i + 1}일 전`,
    };
  });

  return (
    <DashboardTabs
      kpi={kpi}
      recentActivity={recentActivity}
      columns={columns}
      rows={rows}
      initialDetail={initialDetail}
      currentUser={user}
      users={users}
      departments={departments}
    />
  );
}

import { requireUser } from "@/lib/auth";
import { checkPermission } from "@/lib/permissions";
import { redirect } from "next/navigation";
import { getAdminRequestSheet, getAdminWorkflowMatrix } from "@/lib/queries";
import DataTabs from "@/components/data-tabs";

export default async function DataPage() {
  const user = await requireUser();
  if (!checkPermission(user.role, "admin.data", "view")) {
    redirect("/dashboard");
  }

  const requestSheet = getAdminRequestSheet();
  const matrix = getAdminWorkflowMatrix();

  return (
    <DataTabs
      requestRows={requestSheet}
      workflowColumns={matrix.columns}
      workflowRows={matrix.rows}
    />
  );
}
